window.HOEREN_TESTS[68] = {"id":"im-fundbuero","name":"Im Fundbüro","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist das Fundbüro am Hauptbahnhof. Sie haben gestern nach einer braunen Tasche gefragt. Gute Nachricht: Die Tasche wurde abgegeben. Aber nicht der Geldbeutel darin — der fehlt leider. Den Ausweis haben wir auch nicht gefunden. Bitte kommen Sie zum Abholen, das Fundbüro ist bis 18 Uhr offen. Bringen Sie Ihren Ausweis mit!","gender":"f","q":"Was wurde abgegeben?","opts":["Die Tasche.","Der Geldbeutel.","Der Ausweis."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Hör mal, ich habe meinen Hausschlüssel in der Bahn verloren, nicht mein Handy und nicht meine Tasche. Totale Katastrophe! Ich habe schon beim Fundbüro angerufen, aber noch nichts. Kann ich heute Nacht bei dir schlafen? Morgen rufe ich nochmal an. Vielleicht hat ihn jemand gefunden. Ruf zurück!","gender":"m","q":"Was hat Markus verloren?","opts":["Sein Handy.","Seinen Hausschlüssel.","Seine Tasche."],"correct":1},{"transcript":"Achtung Fahrgäste: Wer einen Gegenstand im Bus oder in der Bahn verliert, kann beim Fundbüro nachfragen. Aber bitte erst nach drei Tagen — nicht am selben Tag und nicht erst nach einer Woche. So lange dauert es, bis die Sachen bei uns ankommen. Online können Sie auch eine Verlustmeldung machen. Danke!","gender":"m","q":"Nach wie vielen Tagen soll man nachfragen?","opts":["Am selben Tag.","Nach drei Tagen.","Nach einer Woche."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Stell dir vor, jemand hat meine Geldbörse gefunden und im Fundbüro abgegeben — mit allem Geld drin! Sie wurde nicht gestohlen, und sie ist auch nicht noch weg. Ich bin so erleichtert. Es gibt noch ehrliche Menschen. Ich möchte mich bedanken, aber ich weiß nicht, wer es war. Toll, oder?","gender":"f","q":"Was ist mit Annas Geldbörse passiert?","opts":["Sie wurde gestohlen.","Sie ist noch weg.","Sie wurde gefunden und abgegeben."],"correct":2},{"transcript":"Liebe Bürger: Gefundene Sachen bewahren wir sechs Monate auf, nicht drei Monate und nicht ein Jahr. Wer seinen Gegenstand nicht abholt, verliert ihn danach. Wertvolle Sachen wie Schmuck werden dann verkauft. Wer etwas findet, soll es bitte bei uns abgeben — der Finder bekommt manchmal einen kleinen Finderlohn. Danke für Ihre Ehrlichkeit!","gender":"f","q":"Wie lange werden gefundene Sachen aufbewahrt?","opts":["Drei Monate.","Ein Jahr.","Sechs Monate."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat was verloren? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Das Fundbüro hat heute bis fünf geöffnet."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du mitkommst. Nach dem Fest fehlt bei uns einiges."},{"speaker":"Lukas","gender":"m","text":"Ich habe meinen Regenschirm im Bus liegen lassen. Der war blau und ganz nass."},{"speaker":"Lisa","gender":"f","text":"Ich suche mein Handy. Es lag auf der Bank im Park und war plötzlich weg."},{"speaker":"Lukas","gender":"m","text":"Fehlt jemandem von uns auch eine Tasche?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Tasche vermisst hier niemand."},{"speaker":"Lukas","gender":"m","text":"Tom ist heute Morgen ganz blass geworden."},{"speaker":"Lisa","gender":"f","text":"Tom vermisst seinen Geldbeutel. Darin lagen die Karte und etwas Bargeld."},{"speaker":"Lukas","gender":"m","text":"Sara erkennt die Schilder am Gang kaum noch."},{"speaker":"Lisa","gender":"f","text":"Sara vermisst ihre Brille. Ohne die Gläser findet sie den Schalter nur schwer."},{"speaker":"Lukas","gender":"m","text":"Fehlt jemandem ein Laptop aus dem Kurs?"},{"speaker":"Lisa","gender":"f","text":"Nein. Einen Laptop suchen wir nicht. Das Gerät steht noch im Kursraum."},{"speaker":"Lukas","gender":"m","text":"Tim steht seit einer Stunde vor der Wohnung und wartet."},{"speaker":"Lisa","gender":"f","text":"Tim fehlen seine Schlüssel. Sie steckten noch an der Garderobe im Flur."},{"speaker":"Lukas","gender":"m","text":"Dann nennen wir an der Theke genau diese fünf Sachen."},{"speaker":"Lisa","gender":"f","text":"Die Nummer vom Bus steht schon auf meinem Zettel."}],"options":[{"letter":"a","text":"Regenschirm"},{"letter":"b","text":"Tasche"},{"letter":"c","text":"Jacke"},{"letter":"d","text":"Schlüssel"},{"letter":"e","text":"Handy"},{"letter":"f","text":"Laptop"},{"letter":"g","text":"Brille"},{"letter":"h","text":"Uhr"},{"letter":"i","text":"Geldbeutel"}],"items":[{"person":"Lukas","correct":"a"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich suche eine rote Jacke. Ich habe sie vielleicht im Bus oder im Zug verloren."},{"speaker":"Mitarbeiter","gender":"m","text":"Wann haben Sie sie verloren? Im Bus oder im Zug?"},{"speaker":"Kundin","gender":"f","text":"Nicht im Bus und nicht im Zug. Vorgestern in der U-Bahn."},{"speaker":"Mitarbeiter","gender":"m","text":"Einen Moment, ich schaue nach. Rot, U-Bahn, vorgestern."},{"speaker":"Kundin","gender":"f","text":"Danke, ich warte hier. Hoffentlich ist die Jacke da."}],"q":"Wo hat die Kundin die Jacke verloren?","opts":["In der U-Bahn.","Im Bus.","Im Zug."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, ich suche nichts und ich hole auch nichts ab. Ich habe diesen Schlüssel gefunden."},{"speaker":"Mitarbeiterin","gender":"f","text":"Sehr nett, danke. Also Sie geben etwas ab. Wo war das?"},{"speaker":"Mann","gender":"m","text":"Auf einer Bank im Park, heute Morgen."},{"speaker":"Mitarbeiterin","gender":"f","text":"Ich notiere das, vielen Dank. Sie geben den Fund bei uns ab, das ist hilfreich."},{"speaker":"Mann","gender":"m","text":"Gern. Ich hoffe, der Besitzer kommt bald."}],"q":"Was macht der Mann?","opts":["Er sucht etwas.","Er gibt etwas ab.","Er holt etwas ab."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, was muss ich zum Abholen mitbringen? Geld oder ein Foto, oder etwas anderes?"},{"speaker":"Mitarbeiter","gender":"m","text":"Kein Geld und kein Foto. Einen Ausweis."},{"speaker":"Frau","gender":"f","text":"Reicht der Führerschein als Ausweis?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, der Führerschein geht auch. Also Ausweis mitbringen, bitte."},{"speaker":"Frau","gender":"f","text":"Gut, ich habe den Führerschein dabei, also meinen Ausweis. Danke schön."}],"q":"Was muss die Frau mitbringen?","opts":["Geld.","Einen Ausweis.","Ein Foto."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, kostet das Abholen etwas? Ist es kostenlos oder 5 Euro, können Sie mir das sagen?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Nicht kostenlos und nicht 5 Euro. Eine kleine Gebühr, 3 Euro."},{"speaker":"Kunde","gender":"m","text":"Auch bei einem Schirm, 3 Euro?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, immer drei Euro, auch bei einem Schirm."},{"speaker":"Kunde","gender":"m","text":"Okay, drei Euro Gebühr ist in Ordnung. Hier bitte, danke."}],"q":"Wie hoch ist die Gebühr?","opts":["Kostenlos.","5 Euro.","3 Euro."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, wie lange sind Sie geöffnet? Werktags und vormittags, oder auch später?"},{"speaker":"Mitarbeiter","gender":"m","text":"Werktags von 9 bis 18 Uhr, also auch nachmittags, nicht nur vormittags."},{"speaker":"Mann","gender":"m","text":"Und am Samstag?"},{"speaker":"Mitarbeiter","gender":"m","text":"Samstags geschlossen. Nur werktags, von 9 bis 18 Uhr."},{"speaker":"Mann","gender":"m","text":"Verstehe, samstags geschlossen. Dann komme ich am Montag vormittags. Danke schön Ihnen."}],"q":"Wann ist das Fundbüro geschlossen?","opts":["Werktags.","Vormittags.","Samstags."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Maier, einem Mitarbeiter im Fundbüro. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Maier, Sie arbeiten seit zehn Jahren im Fundbüro. Was wird am häufigsten verloren?"},{"speaker":"Maier","gender":"m","text":"Ganz klar Regenschirme und Handschuhe, vor allem im Winter. Und Handys natürlich, jeden Tag mehrere. Die Leute legen sie weg und vergessen sie. Bei uns stapeln sich die Schirme. Manche holt nie jemand ab — schade um die guten Stücke."},{"speaker":"Reporterin","gender":"f","text":"Was war das Ungewöhnlichste, das abgegeben wurde?"},{"speaker":"Maier","gender":"m","text":"Oh, da gibt es viele Geschichten. Einmal ein Gebiss, einmal ein Glasauge. Sogar ein lebender Hund wurde mal abgegeben, der war im Zug vergessen worden. Und eine ganze Kiste mit Geld. Sie glauben nicht, was die Leute alles liegen lassen."},{"speaker":"Reporterin","gender":"f","text":"Sind die Menschen heute ehrlich?"},{"speaker":"Maier","gender":"m","text":"Ehrlicher, als man denkt. Die meisten geben gefundene Sachen ab, auch wenn Geld drin ist. Das freut mich immer wieder. Klar, manche behalten etwas. Aber die Mehrheit ist ehrlich. Das gibt mir Hoffnung für die Gesellschaft."},{"speaker":"Reporterin","gender":"f","text":"Was passiert mit Sachen, die niemand abholt?"},{"speaker":"Maier","gender":"m","text":"Nach sechs Monaten werden sie versteigert oder gespendet. Wertvolle Sachen kommen in eine Auktion, das Geld geht an die Stadt. Kleidung spenden wir an soziale Einrichtungen. Wegwerfen tun wir fast nichts. Alles soll noch einen Nutzen haben."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie den Leuten?"},{"speaker":"Maier","gender":"m","text":"Schreiben Sie Ihren Namen und eine Nummer in wichtige Sachen. Dann können wir Sie sofort anrufen. Und melden Sie einen Verlust schnell, am besten online. Je genauer Sie den Gegenstand beschreiben, desto leichter finden wir ihn. Geben Sie nicht zu früh auf."}],"items":[{"q":"Es wurde noch nie ein Tier im Fundbüro abgegeben.","correct":"nein"},{"q":"Regenschirme werden besonders oft verloren.","correct":"ja"},{"q":"Herr Maier findet, die meisten Menschen sind ehrlich.","correct":"ja"},{"q":"Sachen, die niemand abholt, werden sofort weggeworfen.","correct":"nein"},{"q":"Er rät, den Namen in wichtige Sachen zu schreiben.","correct":"ja"}]}]};
